def build():
 out={f"models/block/exotic_home/{k}.json":v for k,v in MODELS.items()};lines=["// GENERATED by tools/gen_exotic_elven_home_pilot.py","const EXOTIC_FACING=BlockProperties.HORIZONTAL_FACING","StartupEvents.registry('block',event=>{"]
 for name in MODELS:
  lines += [f"  let exotic_{name}=event.create('alfheim:{name}','cardinal')",f"    .displayName({json.dumps(name.replace('_',' ').title())})",f"    .model('alfheim:block/exotic_home/{name}')","    .hardness(1.0).resistance(3.0).fullBlock(false).notSolid().noValidSpawns(true)","    .renderType('cutout')","    .box(2, 0, 2, 14, 16, 14)","    .tagBoth('alfheim:exotic_elven_home')",f"  exotic_{name}.rotateState(s=>s.setValue(EXOTIC_FACING,s.rotate(s.getValue(EXOTIC_FACING))))",f"  exotic_{name}.mirrorState(s=>s.setValue(EXOTIC_FACING,s.mirror(s.getValue(EXOTIC_FACING))))",""]
 lines += ["})",""];out["startup"]="\n".join(lines);ids=["alfheim:"+x for x in MODELS];out["tags/blocks/exotic_elven_home.json"]={"replace":False,"values":ids};out["tags/items/exotic_elven_home.json"]={"replace":False,"values":ids}
 review=["# GENERATED by tools/gen_exotic_elven_home_pilot.py","say [Alfheim] placing exotic home pilot"]+[f"setblock ~{i*3} ~ ~0 alfheim:{name}[facing=north]" for i,name in enumerate(MODELS)]+["say [Alfheim] exotic home pilot placed",""];out["review"]="\n".join(review);return out
