 p=argparse.ArgumentParser();p.add_argument("--check",action="store_true");q=p.parse_args();bad=[]
 for k,v in build().items():
  raw=(v if isinstance(v,str) else json.dumps(v,separators=(",",":"))+"\n").encode();dest=path(k)
  if q.check:
   if not dest.exists() or dest.read_bytes()!=raw:bad.append(str(dest.relative_to(ROOT)))
  else:dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(raw)
 if bad:raise SystemExit("Generated output mismatch:\n"+"\n".join(bad))
 print(f"{len(build())} exotic home resources; blocks={len(MODELS)} "+("byte-identical" if q.check else "generated"))
